cleanupProbeSource:
import {lstatSync,readFileSync,realpathSync,rmSync} from 'node:fs';
import {tmpdir} from 'node:os';
import {join,dirname} from 'node:path';
const parent=realpathSync(tmpdir());
const dir=join(parent,'memory-test-LMx8gD');
const stat=lstatSync(dir,{bigint:true,throwIfNoEntry:false});
if(!stat){console.log('Probe allocation already absent');process.exit(0);}
const marker=join(dir,'.memory-test-owner.json');
const ms=lstatSync(marker);
const owner=JSON.parse(readFileSync(marker,'utf8'));
if(!stat.isDirectory()||stat.isSymbolicLink()||realpathSync(dir)!==dir||dirname(dir)!==parent||!ms.isFile()||ms.isSymbolicLink()||ms.nlink!==1||owner.project!=='memory-nexus'||owner.dir!==dir||owner.device!==stat.dev.toString()||owner.inode!==stat.ino.toString())throw Error('Refusing changed probe ownership');
rmSync(dir,{recursive:true,force:false});
console.log('Reclaimed only the identified failed GC probe allocation after ownership verification.');

consistency.validatorSource:
import {readFileSync,writeFileSync} from 'node:fs';
import {sourceHash,validateInventory} from '../scripts/quality-inventory';
const root='.planning/memory-resilience/';
const read=(p:string)=>JSON.parse(readFileSync(p,'utf8'));
const assert=(v:unknown,m:string)=>{if(!v)throw Error(m);};
const catalog=read(root+'executable-catalog.json'), manifest=read(root+'quality-classifications.json'), ledger=read(root+'work-items.json');
assert(catalog.files.length===448&&!validateInventory(catalog,manifest).length,'Invalid inventory');
for(const input of [...catalog.files,...catalog.packages])assert(sourceHash(readFileSync(input.path,'utf8'))===input.sourceHash,'Stale source '+input.path);
const byId=new Map<string,any>(ledger.items.map((x:any)=>[x.id,x]));
assert(byId.size===218,'Ledger count changed');
function visit(id:string,path=new Set<string>()){
 assert(byId.has(id)&&!path.has(id),'Invalid dependency '+id);
 for(const dep of byId.get(id).depends_on)visit(dep,new Set([...path,id]));
}
for(const id of byId.keys())visit(id);
assert(ledger.items.filter((x:any)=>x.status==='active').map((x:any)=>x.id).join()==='B11.1','Wrong active item');
assert(byId.get('B04').status==='blocked'&&byId.get('B05').status==='pending','Premature acceptance');
const evidence=read(root+'evidence/B11.1.json');
for(const input of evidence.sourceInputs)assert(sourceHash(readFileSync(input.path,'utf8'))===input.sourceHash,'Stale repair evidence '+input.path);
for(const path of ['tests/helpers/test-database.ts','tests/helpers/owned-test-directory.ts','tests/helpers/test-database.test.ts'])assert(manifest.files.find((x:any)=>x.path===path).metricApplicability.status.startsWith('invalidated'),'Stale applicability accepted');
evidence.checks.push({command:'bun run quality:inventory',exit:0,result:'448 files and two packages structurally valid; not review/coverage approval.',output:readFileSync('.git/b11-1-inventory.txt','utf8')});
evidence.consistency={sourceBindings:448,packages:2,ledgerItems:218,acyclic:true,activeItem:'B11.1',staleApplicabilityInvalidated:true,validatorSource:readFileSync('.git/b11-validate.ts','utf8')};
writeFileSync(root+'evidence/B11.1.json',JSON.stringify(evidence,null,2)+'\n');
console.log('PASS: source-bound repair evidence, full structural inventory and dependency ledger; acceptance remains open.');
